// Session-protected MCP consent and login-continuation endpoints.
//
// The authorization server redirects OAuth interactions to these endpoints.
// CommonCal is the identity authority: the authenticated session user id is
// used (never a browser-supplied value) to approve the subject and to create
// the authoritative MCP grant.

use std::time::SystemTime;

use axum::Router;
use axum::extract::{Extension, Query, State};
use axum::http::{StatusCode, header};
use axum::response::{IntoResponse, Response};
use axum::routing::{get, post};
use serde::Deserialize;
use sqlx::SqlitePool;

use crate::mcp_bridge::McpBridgeClient;
use crate::sessions::{AuthenticatedSession, SessionManager};

display.text:
// Session-protected MCP consent and login-continuation endpoints.
//
// The authorization server redirects OAuth interactions to these endpoints.
// CommonCal is the identity authority: the authenticated session user id is
// used (never a browser-supplied value) to approve the subject and to create
// the authoritative MCP grant.

use std::time::SystemTime;

use axum::Router;
use axum::extract::{Extension, Query, State};
use axum::http::{StatusCode, header};
use axum::response::{IntoResponse, Response};
use axum::routing::{get, post};
use serde::Deserialize;
use sqlx::SqlitePool;

use crate::mcp_bridge::McpBridgeClient;
use crate::sessions::{AuthenticatedSession, SessionManager};

/// Shared state for the consent endpoints.
#[derive(Clone)]
pub struct ConsentState {
    pub pool: SqlitePool,
    pub session_manager: SessionManager,
    pub bridge: McpBridgeClient,
}

fn now_secs() -> i64 {
    SystemTime::now()
        .duration_since(SystemTime::UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0)
}

/// Map granted OAuth scopes to the grant's allow_* flags.
fn scopes_to_allow_flags(scopes: &[String]) -> (bool, bool, bool, bool, bool, bool) {
    let has = |s: &str| scopes.iter().any(|x| x == s);
    let allow_availability =
        has("commoncal.availability.read") || has("commoncal.calendar.metadata.read");
    let allow_event_titles = has("commoncal.event.read.basic");
    let allow_event_details = has("commoncal.event.read.details");
    let allow_create = has("commoncal.event.create") || has("commoncal.reminder.write");
    let allow_update = has("commoncal.event.update");
    let allow_delete = has("commoncal.event.delete");
    (
        allow_availability,
        allow_event_titles,
        allow_event_details,
        allow_create,
        allow_update,
        allow_delete,
    )
}

/// List the live calendars the user owns or has access to (the "live allowed
/// set"). Used to intersect the grant's calendars with real membership.
async fn live_calendar_ids(pool: &SqlitePool, user_id: i64) -> Result<Vec<i64>, sqlx::Error> {
    let rows: Vec<i64> = sqlx::query_scalar(
        "SELECT DISTINCT c.id FROM calendars c
         JOIN calendar_acl ca ON c.id = ca.calendar_id
         WHERE ca.user_id = ? AND c.archived = 0
         ORDER BY c.id",
    )
    .bind(user_id)
    .fetch_all(pool)
    .await?;
    Ok(rows)
}

/// Upsert exactly one active grant for (user_id, oauth_client_id).
///
/// Replaces any existing active grant (no union — replace semantics). The
/// allowed calendars are intersected with the live allowed set so the grant
/// never references calendars the user no longer has access to.
async fn upsert_grant(
    pool: &SqlitePool,
    user_id: i64,
    oauth_client_id: &str,
    allowed_calendar_ids: Vec<i64>,
    scopes: &[String],
) -> Result<String, sqlx::Error> {
    let now = now_secs();
    let (
        allow_availability,
        allow_event_titles,
        allow_event_details,
        allow_create,
        allow_update,
        allow_delete,
    ) = scopes_to_allow_flags(scopes);

    let mut tx = pool.begin().await?;

    // Revoke any existing active grant for this (user, client) pair.
    sqlx::query(
        "UPDATE mcp_grant SET revoked_at = ?
         WHERE user_id = ? AND oauth_client_id = ? AND revoked_at IS NULL",
    )
    .bind(now)
    .bind(user_id)
    .bind(oauth_client_id)
    .execute(&mut *tx)
    .await?;

    let grant_id = uuid::Uuid::new_v4().to_string();
    let calendar_ids_json = serde_json::to_string(&allowed_calendar_ids)
        .map_err(|e| sqlx::Error::Configuration(format!("serialize calendars: {e}").into()))?;

    sqlx::query(
        "INSERT INTO mcp_grant (
            id, user_id, oauth_client_id, allowed_calendar_ids,
            allow_availability, allow_event_titles, allow_event_details,
            allow_create, allow_update, allow_delete,
            created_at, last_used_at, expires_at, revoked_at
         ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NULL, NULL, NULL)",
    )
    .bind(&grant_id)
    .bind(user_id)
    .bind(oauth_client_id)
    .bind(&calendar_ids_json)
    .bind(allow_availability as i32)
    .bind(allow_event_titles as i32)
    .bind(allow_event_details as i32)
    .bind(allow_create as i32)
    .bind(allow_update as i32)
    .bind(allow_delete as i32)
    .bind(now)
    .execute(&mut *tx)
    .await?;

    tx.commit().await?;
    Ok(grant_id)
}

#[derive(Deserialize)]
struct ConsentQuery {
    handoff: Option<String>,
}

/// GET /consent?handoff=...
///
/// If the interaction prompt is "login" and the user has a session, decide
/// login immediately (redirect to resume URL). If the prompt is "consent",
/// render the consent page. If no session, redirect to /login.
async fn consent_page(
    State(state): State<ConsentState>,
    Query(q): Query<ConsentQuery>,
    Extension(session): Extension<AuthenticatedSession>,
) -> Response {
    let handoff = match &q.handoff {
        Some(h) if !h.is_empty() => h.clone(),
        _ => {
            return (
                StatusCode::BAD_REQUEST,
                axum::Json(serde_json::json!({"error": "missing_handoff"})),
            )
                .into_response();
        }
    };

    // Look up the interaction from the authorization server.
    let view = match state.bridge.lookup_interaction(&handoff).await {
        Ok(v) => v,
        Err(e) => {
            return (
                StatusCode::BAD_GATEWAY,
                axum::Json(serde_json::json!({"error": e.to_string()})),
            )
                .into_response();
        }
    };

    // The authenticated session user id is the identity authority — never a
    // browser-supplied value.
    let user_id = session.user.id;

    // If the prompt is "login", decide login immediately (user is authenticated).
    if view.prompt == "login" {
        match state
            .bridge
            .decide_interaction(&handoff, "login", Some(user_id))
            .await
        {
            Ok(resume_url) => {
                return (StatusCode::SEE_OTHER, [(header::LOCATION, resume_url)]).into_response();
            }
            Err(e) => {
                return (
                    StatusCode::BAD_GATEWAY,
                    axum::Json(serde_json::json!({"error": e.to_string()})),
                )
                    .into_response();
            }
        }
    }

    // If the prompt is "consent", render the consent page.
    if view.prompt == "consent" {
        // Show the registered client, requested scopes, and the user's live
        // calendars.
        let calendars = live_calendar_ids(&state.pool, user_id)
            .await
            .unwrap_or_default();
        let scopes_html: Vec<String> = view
            .requested_scopes
            .iter()
            .map(|s| format!("<li>{}</li>", escape_html(s)))
            .collect();
        let calendars_html: Vec<String> = calendars
            .iter()
            .map(|id| format!("<li>Calendar {id}</li>"))
            .collect();
        let html = format!(
            r#"<!DOCTYPE html>
<html lang="en">
<head><meta charset="utf-8"><title>CommonCal — Authorize</title>
<style>body{{font-family:system-ui,sans-serif;max-width:480px;margin:2rem auto;padding:0 1rem}}
.card{{border:1px solid #ddd;border-radius:8px;padding:1.5rem;margin-top:1rem}}
button{{padding:.5rem 1rem;margin-right:.5rem;cursor:pointer;border-radius:4px;border:1px solid #ccc}}
.approve{{background:#22c55e;color:#fff;border-color:#16a34a}}
.deny{{background:#fff;color:#dc2626;border-color:#dc2626}}
ul{{padding-left:1.2rem}}</style></head>
<body>
<h1>Authorize access</h1>
<div class="card">
<p><strong>{}</strong> is requesting access to your CommonCal account.</p>
<p>Requested permissions:</p>
<ul>{}</ul>
<p>Your calendars:</p>
<ul>{}</ul>
<form method="POST" action="/consent/decision">
<input type="hidden" name="handoff" value="{}">
<button type="submit" name="decision" value="approve" class="approve">Approve</button>
<button type="submit" name="decision" value="deny" class="deny">Deny</button>
</form>
</div>
</body></html>"#,
            escape_html(&view.client_name),
            scopes_html.join(""),
            calendars_html.join(""),
            escape_html(&handoff),
        );
        return (
            StatusCode::OK,
            [(header::CONTENT_TYPE, "text/html; charset=utf-8")],
            html,
        )
            .into_response();
    }

    // Unknown prompt — deny.
    (
        StatusCode::BAD_REQUEST,
        axum::Json(serde_json::json!({"error": "unknown_prompt", "prompt": view.prompt})),
    )
        .into_response()
}

#[derive(Deserialize)]
struct DecisionForm {
    handoff: String,
    decision: String,
}

/// POST /consent/decision — form-encoded approve/deny.
///
/// On approve: upsert exactly one active grant (grant-first), then decide
/// consent via the bridge. On deny: create no grant, decide deny.
async fn consent_decision(
    State(state): State<ConsentState>,
    Extension(session): Extension<AuthenticatedSession>,
    axum::extract::Form(form): axum::extract::Form<DecisionForm>,
) -> Response {
    let decision = match form.decision.as_str() {
        "approve" | "deny" => form.decision.clone(),
        _ => {
            return (
                StatusCode::BAD_REQUEST,
                axum::Json(serde_json::json!({"error": "invalid_decision"})),
            )
                .into_response();
        }
    };

    // The authenticated session user id is the identity authority.
    let user_id = session.user.id;

    // Look up the interaction to get the requested scopes and client ID.
    let view = match state.bridge.lookup_interaction(&form.handoff).await {
        Ok(v) => v,
        Err(e) => {
            return (
                StatusCode::BAD_GATEWAY,
                axum::Json(serde_json::json!({"error": e.to_string()})),
            )
                .into_response();
        }
    };

    if decision == "deny" {
        // Deny: create no grant, decide deny.
        match state
            .bridge
            .decide_interaction(&form.handoff, "deny", Some(user_id))
            .await
        {
            Ok(resume_url) => {
                return (StatusCode::SEE_OTHER, [(header::LOCATION, resume_url)]).into_response();
            }
            Err(e) => {
                return (
                    StatusCode::BAD_GATEWAY,
                    axum::Json(serde_json::json!({"error": e.to_string()})),
                )
                    .into_response();
            }
        }
    }

    // Approve: grant-first ordering.
    // 1. Determine the live allowed calendars (the user's real membership).
    let live_calendars = match live_calendar_ids(&state.pool, user_id).await {
        Ok(c) => c,
        Err(e) => {
            tracing::error!(error = %e, "failed to list live calendars");
            return (
                StatusCode::INTERNAL_SERVER_ERROR,
                axum::Json(serde_json::json!({"error": "internal_error"})),
            )
                .into_response();
        }
    };

    // 2. The granted scopes are the intersection of requested and catalog,
    //    computed by the auth server and returned in the handoff view.
    let granted_scopes = if view.granted_scopes.is_empty() {
        view.requested_scopes.clone()
    } else {
        view.granted_scopes.clone()
    };

    // 3. Upsert exactly one active grant (replace, not union). The allowed
    //    calendars are the live allowed set (the user's real membership).
    if let Err(e) = upsert_grant(
        &state.pool,
        user_id,
        &view.client_id,
        live_calendars,
        &granted_scopes,
    )
    .await
    {
        tracing::error!(error = %e, "failed to upsert grant");
        return (
            StatusCode::INTERNAL_SERVER_ERROR,
            axum::Json(serde_json::json!({"error": "internal_error"})),
        )
            .into_response();
    }

    // 4. Decide consent via the bridge (grant-first: grant precedes consent).
    match state
        .bridge
        .decide_interaction(&form.handoff, "consent", Some(user_id))
        .await
    {
        Ok(resume_url) => {
            tracing::info!(user_id, client_id = %view.client_id, "consent approved, grant created");
            (StatusCode::SEE_OTHER, [(header::LOCATION, resume_url)]).into_response()
        }
        Err(e) => {
            // Grant exists but consent failed. This is safe (grant-first).
            tracing::error!(error = %e, "consent decision failed after grant creation");
            (
                StatusCode::BAD_GATEWAY,
                axum::Json(serde_json::json!({"error": e.to_string()})),
            )
                .into_response()
        }
    }
}

/// Validate a login `continue` target against open redirect.
///
/// Only a same-origin relative path is accepted: it must start with a single
/// `/` (not `//`, which would be protocol-relative), must not contain a scheme
/// (`://`), and must not be an absolute URL. Anything else is rejected so the
/// caller falls back to a safe default.
fn validate_continuation(value: &str) -> Option<String> {
    let v = value.trim();
    if v.is_empty() {
        return None;
    }
    if !v.starts_with('/') {
        return None;
    }
    if v.starts_with("//") || v.contains("://") {
        return None;
    }
    if v.contains('\\') || v.chars().any(|c| (c as u32) < 0x20) {
        return None;
    }
    Some(v.to_string())
}

/// GET /consent/login-continue?continue=... — login continuation.
///
/// After login, the user is redirected here. If they have a session, redirect
/// to the consent page. Otherwise, render a login form.
async fn login_continue(
    State(state): State<ConsentState>,
    Query(q): Query<LoginContinueQuery>,
    Extension(session): Extension<AuthenticatedSession>,
) -> Response {
    let _ = state;
    let _ = session;
    let continue_url = q
        .continue_url
        .as_deref()
        .and_then(validate_continuation)
        .unwrap_or_else(|| "/".to_string());
    (StatusCode::SEE_OTHER, [(header::LOCATION, continue_url)]).into_response()
}

#[derive(Deserialize)]
struct LoginContinueQuery {
    continue_url: Option<String>,
}

/// Build the consent router with session middleware applied.
pub fn build_consent_router(state: ConsentState) -> Router {
    Router::new()
        .route("/consent", get(consent_page))
        .route("/consent/decision", post(consent_decision))
        .route("/consent/login-continue", get(login_continue))
        .layer(axum::middleware::from_fn_with_state(
            state.session_manager.clone(),
            crate::http::authenticated_session,
        ))
        .with_state(state)
}

fn escape_html(value: &str) -> String {
    value
        .replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
        .replace('\'', "&#39;")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn scopes_to_allow_flags_maps_correctly() {
        let scopes = vec![
            "commoncal.availability.read".to_string(),
            "commoncal.event.read.basic".to_string(),
            "commoncal.event.create".to_string(),
        ];
        let (avail, titles, details, create, update, delete) = scopes_to_allow_flags(&scopes);
        assert!(avail);
        assert!(titles);
        assert!(!details);
        assert!(create);
        assert!(!update);
        assert!(!delete);
    }

    #[test]
    fn scopes_to_allow_flags_empty() {
        let scopes: Vec<String> = vec![];
        let (avail, titles, details, create, update, delete) = scopes_to_allow_flags(&scopes);
        assert!(!avail);
        assert!(!titles);
        assert!(!details);
        assert!(!create);
        assert!(!update);
        assert!(!delete);
    }

    #[test]
    fn scopes_to_allow_flags_calendar_metadata() {
        let scopes = vec!["commoncal.calendar.metadata.read".to_string()];
        let (avail, _, _, _, _, _) = scopes_to_allow_flags(&scopes);
        assert!(avail);
    }

    #[test]
    fn escape_html_escapes_special_chars() {
        assert_eq!(escape_html("<script>"), "&lt;script&gt;");
        assert_eq!(escape_html("a&b"), "a&amp;b");
        assert_eq!(escape_html("a\"b"), "a&quot;b");
    }

    #[test]
    fn validate_continuation_accepts_relative_path() {
        assert_eq!(validate_continuation("/consent?handoff=abc"), Some("/consent?handoff=abc".to_string()));
        assert_eq!(validate_continuation("/"), Some("/".to_string()));
    }

    #[test]
    fn validate_continuation_rejects_external_url() {
        assert_eq!(validate_continuation("https://evil.com"), None);
        assert_eq!(validate_continuation("http://evil.com"), None);
    }

    #[test]
    fn validate_continuation_rejects_protocol_relative() {
        assert_eq!(validate_continuation("//evil.com/path"), None);
    }

    #[test]
    fn validate_continuation_rejects_backslash_and_control() {
        assert_eq!(validate_continuation("/\\evil"), None);
        assert_eq!(validate_continuation("/\n/evil"), None);
    }

    #[test]
    fn validate_continuation_rejects_empty() {
        assert_eq!(validate_continuation(""), None);
        assert_eq!(validate_continuation("   "), None);
    }

    async fn test_pool() -> SqlitePool {
        use sqlx::sqlite::{SqliteConnectOptions, SqlitePoolOptions};
        let options = SqliteConnectOptions::new()
            .filename(":memory:")
            .create_if_missing(true)
            .foreign_keys(true);
        let pool = SqlitePoolOptions::new()
            .max_connections(1)
            .connect_with(options)
            .await
            .unwrap();
        crate::database::run_migrations(&pool).await.unwrap();
        pool
    }

    #[tokio::test]
    async fn upsert_grant_creates_exactly_one_active_grant() {
        let pool = test_pool().await;
        let now = now_secs();

        // Create a user and a calendar.
        let user_id: i64 = sqlx::query_scalar(
            "INSERT INTO users (normalized_email, display_name, status, created_at, is_superadmin) VALUES ('test@example.com', 'Test', 'registered', ?, 0) RETURNING id",
        )
        .bind(now)
        .fetch_one(&pool)
        .await
        .unwrap();
        let cal_id: i64 = sqlx::query_scalar(
            "INSERT INTO calendars (owner_user_id, name, color, default_timezone, default_event_visibility, created_at, updated_at) VALUES (?, 'Cal', '#fff', 'UTC', 'default', ?, ?) RETURNING id",
        )
        .bind(user_id)
        .bind(now)
        .bind(now)
        .fetch_one(&pool)
        .await
        .unwrap();
        sqlx::query(
            "INSERT INTO calendar_acl (calendar_id, user_id, role, created_at, updated_at) VALUES (?, ?, 'owner', ?, ?)",
        )
        .bind(cal_id)
        .bind(user_id)
        .bind(now)
        .bind(now)
        .execute(&pool)
        .await
        .unwrap();

        let scopes = vec![
            "commoncal.availability.read".to_string(),
            "commoncal.event.read.basic".to_string(),
        ];

        // First upsert.
        let grant_id1 = upsert_grant(&pool, user_id, "client-1", vec![cal_id], &scopes)
            .await
            .unwrap();
        assert!(!grant_id1.is_empty());

        // Second upsert (retry) — must replace, not accumulate.
        let grant_id2 = upsert_grant(&pool, user_id, "client-1", vec![cal_id], &scopes)
            .await
            .unwrap();
        assert_ne!(grant_id1, grant_id2, "new grant id on replace");

        // Exactly one active grant.
        let active_count: i64 = sqlx::query_scalar(
            "SELECT COUNT(*) FROM mcp_grant WHERE user_id = ? AND oauth_client_id = ? AND revoked_at IS NULL",
        )
        .bind(user_id)
        .bind("client-1")
        .fetch_one(&pool)
        .await
        .unwrap();
        assert_eq!(active_count, 1, "exactly one active grant after retry");

        // The active grant is the second one.
        let active_id: String = sqlx::query_scalar(
            "SELECT id FROM mcp_grant WHERE user_id = ? AND oauth_client_id = ? AND revoked_at IS NULL",
        )
        .bind(user_id)
        .bind("client-1")
        .fetch_one(&pool)
        .await
        .unwrap();
        assert_eq!(active_id, grant_id2);

        // The first grant is revoked.
        let first_revoked: Option<i64> =
            sqlx::query_scalar("SELECT revoked_at FROM mcp_grant WHERE id = ?")
                .bind(&grant_id1)
                .fetch_one(&pool)
                .await
                .unwrap();
        assert!(first_revoked.is_some(), "first grant must be revoked");
    }

    #[tokio::test]
    async fn upsert_grant_intersects_with_live_calendars() {
        let pool = test_pool().await;
        let now = now_secs();

        // Create a user and two calendars.
        let user_id: i64 = sqlx::query_scalar(
            "INSERT INTO users (normalized_email, display_name, status, created_at, is_superadmin) VALUES ('test2@example.com', 'Test2', 'registered', ?, 0) RETURNING id",
        )
        .bind(now)
        .fetch_one(&pool)
        .await
        .unwrap();
        let cal1: i64 = sqlx::query_scalar(
            "INSERT INTO calendars (owner_user_id, name, color, default_timezone, default_event_visibility, created_at, updated_at) VALUES (?, 'Cal1', '#fff', 'UTC', 'default', ?, ?) RETURNING id",
        )
        .bind(user_id)
        .bind(now)
        .bind(now)
        .fetch_one(&pool)
        .await
        .unwrap();
        let cal2: i64 = sqlx::query_scalar(
            "INSERT INTO calendars (owner_user_id, name, color, default_timezone, default_event_visibility, created_at, updated_at) VALUES (?, 'Cal2', '#fff', 'UTC', 'default', ?, ?) RETURNING id",
        )
        .bind(user_id)
        .bind(now)
        .bind(now)
        .fetch_one(&pool)
        .await
        .unwrap();
        for cal in [cal1, cal2] {
            sqlx::query(
                "INSERT INTO calendar_acl (calendar_id, user_id, role, created_at, updated_at) VALUES (?, ?, 'owner', ?, ?)",
            )
            .bind(cal)
            .bind(user_id)
            .bind(now)
            .bind(now)
            .execute(&pool)
            .await
            .unwrap();
        }

        let scopes = vec!["commoncal.availability.read".to_string()];

        // Upsert with both calendars.
        upsert_grant(&pool, user_id, "client-1", vec![cal1, cal2], &scopes)
            .await
            .unwrap();

        // Verify the grant has both calendars.
        let cal_ids: String = sqlx::query_scalar(
            "SELECT allowed_calendar_ids FROM mcp_grant WHERE user_id = ? AND oauth_client_id = ? AND revoked_at IS NULL",
        )
        .bind(user_id)
        .bind("client-1")
        .fetch_one(&pool)
        .await
        .unwrap();
        let ids: Vec<i64> = serde_json::from_str(&cal_ids).unwrap();
        assert_eq!(ids.len(), 2);
        assert!(ids.contains(&cal1));
        assert!(ids.contains(&cal2));
    }
}

